def solve(coins, amount):
    if amount == 0:
        return 0
    coins = sorted(set(coins), reverse=True)
    INF = float('inf')
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c > i:
                continue
            if dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

